const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open);menu.textContent=open?'Close −':'Menu +'});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});
document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));
document.querySelectorAll('[data-count]').forEach(el=>{const n=Number(el.dataset.count);if(reduced)return;const o=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){let start;function tick(t){start??=t;const p=Math.min((t-start)/1300,1);el.textContent=Math.floor(n*(1-Math.pow(1-p,3)))+'+';if(p<1)requestAnimationFrame(tick)}requestAnimationFrame(tick);o.disconnect()}},{threshold:.5});o.observe(el)});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');document.querySelectorAll('[data-category]').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter)}));
const dialog=document.querySelector('#lightbox');document.querySelectorAll('[data-lightbox]').forEach(b=>b.addEventListener('click',()=>{dialog.querySelector('img').src=b.dataset.lightbox;dialog.querySelector('img').alt=b.dataset.caption;dialog.querySelector('p').textContent=b.dataset.caption;dialog.showModal()}));dialog?.querySelector('button').addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
document.querySelector('#enquiry')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const subject=f.get('topic')+' — '+f.get('name');const body=`Name: ${f.get('name')}\nEmail: ${f.get('email')}\nPhone: ${f.get('phone')}\n\n${f.get('message')}`;const email=f.get('topic')==='Franchise partnership'?'franchise@zorko.in':'support@zorko.in';const link=document.querySelector('#email-draft');link.href=`mailto:${email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;document.querySelector('#draft-result').hidden=false;document.querySelector('#draft-result').scrollIntoView({behavior:reduced?'instant':'smooth',block:'center'})});
document.querySelectorAll('a').forEach(a=>{if(a.origin===location.origin&&!a.hash&&!a.hasAttribute('download'))a.addEventListener('click',()=>document.body.classList.add('leaving'))});
addEventListener('pageshow',()=>document.body.classList.remove('leaving'));
const progress=document.querySelector('.reading-progress');addEventListener('scroll',()=>{const h=document.documentElement;progress.style.width=(scrollY/(h.scrollHeight-innerHeight)*100)+'%'},{passive:true});
const topic=new URLSearchParams(location.search).get('topic');const topicSelect=document.querySelector('select[name="topic"]');if(topicSelect&&[...topicSelect.options].some(o=>o.value===topic))topicSelect.value=topic;
const header=document.querySelector('header');let motionPending=false;
function updateMotion(){header?.classList.toggle('is-scrolled',scrollY>35);const backdrop=document.querySelector('.hero-backdrop');if(backdrop&&!reduced&&innerWidth>800){const y=Math.min(scrollY,750);backdrop.style.transform=`translateY(${y*.14}px)`}motionPending=false}
addEventListener('scroll',()=>{if(!motionPending){motionPending=true;requestAnimationFrame(updateMotion)}},{passive:true});updateMotion();
if(!reduced&&matchMedia('(pointer:fine)').matches){document.querySelectorAll('.card .image,.portrait').forEach(card=>{let frame;card.addEventListener('pointermove',e=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const r=card.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(1200px) rotateY(${x*2}deg) rotateX(${-y*2}deg)`})});card.addEventListener('pointerleave',()=>{cancelAnimationFrame(frame);card.style.transform='';card.style.transition='transform .8s cubic-bezier(.16,1,.3,1)'})})}
